import { readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';

// PLO Trainer question banks (generated by trainer/build.py, copied into
// web/data/trainer). The server keeps the answers so challenge scores are
// computed here, not trusted from the browser.

export type Mode = 'range_reads' | 'card_removal' | 'range_vs_range' | 'hero_equity';
export const MODES: Mode[] = ['range_reads', 'card_removal', 'range_vs_range', 'hero_equity'];
export type Game = 'PLO4' | 'PLO5';
export const GAMES: Game[] = ['PLO4', 'PLO5'];

export type Question = {
  id: string;
  mode: Mode;
  game: Game;
  spot: string;
  board: string[];
  texture: string;
  kind: 'estimate' | 'choice';
  template: string;
  prompt: string;
  definition: string;
  position?: string;
  positions?: string[];
  hero?: string[];
  choices?: string[];
  answer?: number;
  baseline?: number;
  correct?: number;
  values?: number[];
};

/** What a player sees before answering: no answer fields. */
export type PublicQuestion = Omit<Question, 'answer' | 'baseline' | 'correct' | 'values'>;
/** Revealed after the player answers. */
export type Reveal = Pick<Question, 'answer' | 'baseline' | 'correct' | 'values'>;

const DIR = path.join(process.cwd(), 'data', 'trainer');

let cache: { all: Question[]; byId: Map<string, Question> } | null = null;

export function bank() {
  if (cache) return cache;
  const all: Question[] = [];
  for (const f of readdirSync(DIR)) {
    if (!f.endsWith('.json')) continue;
    const body = JSON.parse(readFileSync(path.join(DIR, f), 'utf8')) as { questions: Question[] };
    all.push(...body.questions);
  }
  cache = { all, byId: new Map(all.map((q) => [q.id, q])) };
  return cache;
}

export function toPublic(q: Question): PublicQuestion {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const { answer, baseline, correct, values, ...rest } = q;
  return rest;
}

export function reveal(q: Question): Reveal {
  return { answer: q.answer, baseline: q.baseline, correct: q.correct, values: q.values };
}

/** Same formula as the trainer's practice mode (src/lib/scoring.ts). */
export function score(q: Question, guess: number): number {
  if (q.kind === 'choice') return guess === q.correct ? 100 : 0;
  const answer = q.answer ?? 0;
  const tol = Math.max(3, answer * 0.25);
  return Math.round(100 * Math.exp(-Math.abs(guess - answer) / (2 * tol)));
}

type Tally = { up: number; down: number };
function approval(t: Tally | undefined, prior: number) {
  return ((t?.up ?? 0) + prior / 2) / ((t?.up ?? 0) + (t?.down ?? 0) + prior);
}

/**
 * Pick `n` questions for a challenge: feedback-weighted (liked questions more
 * likely), no repeated board, and spread across modes/games when mixed.
 */
export function pickQuestions(
  mode: Mode | 'mixed',
  game: Game | 'mixed',
  n: number,
  stats: { questions: Record<string, Tally>; templates: Record<string, Tally> },
  rand: () => number = Math.random,
): Question[] {
  const modes = mode === 'mixed' ? MODES : [mode];
  const games = game === 'mixed' ? GAMES : [game];
  const slots = Array.from({ length: n }, (_, i) => ({ mode: modes[i % modes.length], game: games[Math.floor(i / modes.length) % games.length] }));
  const usedBoards = new Set<string>();
  const out: Question[] = [];
  for (const slot of slots) {
    const pool = bank().all.filter(
      (q) => q.mode === slot.mode && q.game === slot.game && !usedBoards.has(q.board.join('')),
    );
    if (!pool.length) continue;
    const w = pool.map((q) => Math.max(0.05, 4 * approval(stats.questions[q.id], 4) * approval(stats.templates[q.template], 30)) ** 2);
    let x = rand() * w.reduce((a, b) => a + b, 0);
    let pick = pool[pool.length - 1];
    for (let i = 0; i < pool.length; i++) {
      x -= w[i];
      if (x <= 0) {
        pick = pool[i];
        break;
      }
    }
    usedBoards.add(pick.board.join(''));
    out.push(pick);
  }
  // Shuffle so mixed challenges don't run in a fixed mode order.
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}
